CREATE Proc [dbo].[ReportAssignSubcategory]@DateFrom as datetime, @DateTo as datetime, @SubId as text as Select @DateFrom as [From], @DateTo as [To], ipfp.item_name as Subcategory,ip.item_name as Items,isnull(sum (o.qty),0) as Qty ,ip.Sale_price as Price ,'' as S1, '' as S2, '' as S3,'' as S4,'' as S5, '' as S6, '' as S7, '' as S8,'' as S9, '' as S10, isnull(cast (0 as decimal),0) as d1,isnull(cast (0 as decimal),0) as d2,isnull(cast (0 as decimal),0) as d3,  isnull(cast (0 as decimal),0) as d4,isnull(cast (0 as decimal),0) as d5,isnull(cast (0 as decimal),0) as d6 from ItemPOS_Assign ipa  inner join ItemPOS ip on ipa.item_id=ip.id inner join Order_detail o on ip.id=o.itemid inner join Dine_in_order dio on o.order_key=dio.order_key inner join ItemPOS_finishPro ipfp on ipfp.id=ipa.item_finish_id inner join Split(@SubId,',') sp on sp.items = ipfp.id where o.date between @DateFrom and @DateTo group by ip.Sale_price,ipfp.Item_name,ip.item_name order by ipfp.Item_name,ip.item_name